742 :   // Skill injection: only process user text parts
743 :   const part = event.properties.part as OpenCodePart | undefined;
744 :   if (!part) return;
745 : 
746 :   // Only match skills for text parts (user messages)
747 :   if (part.type !== "text") return;
748 :   const textContent = (part as { text?: string }).text;
749 :   if (!textContent) return;
750 : 
751 :   // Dedup: don't re-process the same part
752 :   const partId = part.id || "";
753 :   if (partId && state.processedMessageParts.has(partId)) return;
754 :   if (partId) state.processedMessageParts.add(partId);
755 : 
756 :   // Cap dedup set size — evict oldest half to avoid cliff-edge re-processing
757 :   if (state.processedMessageParts.size > 1000) {
758 :     const entries = Array.from(state.processedMessageParts);
759 :     const keepFrom = Math.floor(entries.length / 2);
760 :     state.processedMessageParts.clear();
761 :     for (let i = keepFrom; i < entries.length; i++) {
762 :       state.processedMessageParts.add(entries[i]);
763 :     }
764 :     debug(
765 :       SOURCE,
766 :       `Evicted ${keepFrom} entries from processedMessageParts dedup set`,
767 :     );
768 :   }
769 : 
770 :   const prompt = textContent;
771 : 
772 :   // Store latest user prompt so system transform can match skills even if
773 :   // this event fires after the transform (defensive against ordering).
774 :   state.lastUserPrompt = prompt;
775 : 
776 :   // Emit a user-prompt observe event so the convergence detector can find
777 :   // corrective markers near edit sequences. Gated behind AIDE_REFLECT,
