785 :         tokens: Math.round(prompt.length / 3.0),
786 :         session: extractSessionId(event),
787 :         attrs: { text: previewContent(prompt, 2000) },
788 :       });
789 :     } catch {
790 :       // Non-fatal
791 :     }
792 :   }
793 : 
